    h, w = len(grid), len(grid[0])

    # Find separator color and separator rows/cols
    sep_rows = []
    sep_color = None
    for r in range(h):
        vals = set(grid[r])
        if len(vals) == 1:
            v = next(iter(vals))
            if v != 0:
                sep_rows.append(r)
                sep_color = v

    sep_cols = []
    for c in range(w):
        vals = {grid[r][c] for r in range(h)}
        if len(vals) == 1:
            v = next(iter(vals))
            if v == sep_color:
                sep_cols.append(c)

    # 3x3 panel boundaries
    row_blocks = []
    prev = 0
    for sr in sep_rows + [h]:
        row_blocks.append((prev, sr))
        prev = sr + 1

    col_blocks = []
    prev = 0
    for sc in sep_cols + [w]:
        col_blocks.append((prev, sc))
        prev = sc + 1

    # Extract occupied cells in the central 3x3 of each 5x5 panel
    panels = [[set() for _ in range(3)] for _ in range(3)]
    obj_color = None
    for pr in range(3):
        r0, r1 = row_blocks[pr]
        for pc in range(3):
            c0, c1 = col_blocks[pc]
            for i in range(1, 4):
                for j in range(1, 4):
                    rr, cc = r0 + i, c0 + j
                    v = grid[rr][cc]
                    if v != 0 and v != sep_color:
                        panels[pr][pc].add((i - 1, j - 1))
                        obj_color = v

    # Canonical 3x3 templates
    U = {(i, j) for i in range(3) for j in range(3)}
    diamond = {(0, 1), (1, 0), (1, 2), (2, 1)}
    plus = diamond | {(1, 1)}
    ring = U - {(1, 1)}
    hline = {(1, 0), (1, 1), (1, 2)}
    vline = {(0, 1), (1, 1), (2, 1)}
    empty = set()

    candidates = [
        empty,
        diamond,
        plus,
        hline,
        vline,
        ring,
        U,
    ]

    # Search row/col templates minimizing total fill
    best = None
    best_score = None

    for rows_choice in product(range(len(candidates)), repeat=3):
        row_sets = [candidates[i] for i in rows_choice]
        for cols_choice in product(range(len(candidates)), repeat=3):
            col_sets = [candidates[i] for i in cols_choice]

            ok = True
            score = 0
            for r in range(3):
                for c in range(3):
                    target = row_sets[r] | col_sets[c]
                    s = panels[r][c]
                    if not s.issubset(target):
                        ok = False
                        break
                    if s:
                        score += len(target) - len(s)
                    else:
                        score += len(target)
                if not ok:
                    break

            if ok and (best_score is None or score < best_score):
                best_score = score
                best = (row_sets, col_sets)

    row_sets, col_sets = best
    out = [row[:] for row in grid]

    for pr in range(3):
        r0, r1 = row_blocks[pr]
        for pc in range(3):
            c0, c1 = col_blocks[pc]
            target = row_sets[pr] | col_sets[pc]
            for i, j in target:
                rr, cc = r0 + 1 + i, c0 + 1 + j
                if out[rr][cc] == 0:
                    out[rr][cc] = sep_color

    return out

